const express = require('express');
const router = express.Router();
const { db } = require('../db');

router.post('/api/devices/migrate-tokens', requireAdminOrUser, async (req, res) => {
  const { sourceUserId, targetUserId } = req.body;

  if (req.user.id !== sourceUserId && req.user.role !== 'SYSTEM_ADMIN') {
    return res.status(403).json({ error: 'Forbidden: unauthorized token migration request' });
  }

  const updated = await db.query(
    'UPDATE user_push_devices SET user_id = $1 WHERE user_id = $2 RETURNING id, token',
    [targetUserId, sourceUserId]
  );

  return res.json({ migratedCount: updated.rowCount });
});
